"""Dates and times as GitLab and Plane write them, and the day they fall on in a timezone."""
import datetime as dt
import re

UTC = dt.timezone.utc
DATE_ONLY_LENGTH = len("2026-01-31")
AGE_REFERENCE = dt.time(23, 59)  # how long something has been idle is measured up to the end of today


def parse_dt(value):
    """An aware datetime. A date alone is midnight UTC, and a time without offset is UTC."""
    if not value:
        return None
    text = str(value).replace("Z", "+00:00")  # fromisoformat does not accept Z before Python 3.11
    if len(text) == DATE_ONLY_LENGTH:
        text += "T00:00:00+00:00"
    text = re.sub(r"\.(\d+)", six_digit_fraction, text, count=1)
    moment = dt.datetime.fromisoformat(text)
    return moment if moment.tzinfo else moment.replace(tzinfo=UTC)


def six_digit_fraction(match):
    # fromisoformat accepts only 3 or 6 digits before Python 3.11
    return "." + match.group(1).ljust(6, "0")[:6]


def to_date(value):
    """The date of a value that is already a day. For a time, use day_of(): its day depends on the timezone."""
    moment = parse_dt(value)
    return moment.date() if moment else None


def day_of(moment, zone):
    return moment.astimezone(zone).date()


# The limits of a day are returned in UTC, so they can be compared with any other time.
def start_of_day(day, zone):
    return dt.datetime.combine(day, dt.time.min, tzinfo=zone).astimezone(UTC)


def end_of_day(day, zone):
    return dt.datetime.combine(day, dt.time.max, tzinfo=zone).astimezone(UTC)


def age_reference(day, zone):
    return dt.datetime.combine(day, AGE_REFERENCE, tzinfo=zone).astimezone(UTC)


def today_in(zone):
    return day_of(dt.datetime.now(UTC), zone)
